using Greyhaven.Content;
using Microsoft.Xna.Framework;
using Microsoft.Xna.Framework.Graphics;
using Microsoft.Xna.Framework.Input;
namespace Greyhaven.Presentation;
public sealed class CampaignMenu : Game {
 readonly ContentPackage package;readonly string selection;readonly string? capture;readonly GraphicsDeviceManager graphics;SpriteBatch batch=null!;Texture2D pixel=null!,font=null!;RenderTarget2D target=null!;KeyboardState old;MouseState previous;int slot,action,frames;string message="";
 readonly string[] actions=["Continue latest","New campaign","Load manual save","Load quick save","Load autosave","Load exit save"];
 public CampaignMenu(ContentPackage p,string path,string? image){package=p;selection=path;capture=image;graphics=new(this){PreferredBackBufferWidth=1000,PreferredBackBufferHeight=680};Window.Title="Greyhaven - Campaigns";IsMouseVisible=true;}
 protected override void LoadContent(){batch=new(GraphicsDevice);target=new(GraphicsDevice,1000,680,false,SurfaceFormat.Color,DepthFormat.None);pixel=new(GraphicsDevice,1,1);pixel.SetData(new[]{Color.White});using var stream=new MemoryStream(package.ReadBytes("art/compiled/images/font.png","menu-font"));font=Texture2D.FromStream(GraphicsDevice,stream);}
 void Box(int x,int y,int w,int h,Color c)=>batch.Draw(pixel,new Rectangle(x,y,w,h),c);
 void Text(string s,int x,int y,Color? color=null){foreach(char ch in s){int c=Math.Clamp(ch-32,0,95);batch.Draw(font,new Rectangle(x,y,9,18),new Rectangle(c%16*9,c/16*18,9,18),color??Color.Wheat);x+=9;}}
 bool Press(KeyboardState k,Keys key)=>k.IsKeyDown(key)&&!old.IsKeyDown(key);
 void Launch(){try{var store=new CampaignStore(package.Root,"slot"+(slot+1));string mode=action switch{0=>"latest",1=>"new",2=>"manual",3=>"quick",4=>"autosave",_=>"exit"};if(mode=="new"&&store.Exists)throw new ContentException("This slot contains a campaign. Choose an empty slot.");if(mode!="new"){var save=mode=="latest"?store.Latest():store.Read(mode);if(!package.AcceptsFingerprint(save.Fingerprint))throw new ContentException("Save requires a different content package.");}File.WriteAllText(selection,Wire.Encode(new CampaignSelection{Campaign=store.Campaign,Load=mode}));Exit();}catch(Exception e){message=e.Message;}}
 protected override void Update(GameTime time){var k=Keyboard.GetState();var m=Mouse.GetState();int mx=m.X*1000/Math.Max(1,GraphicsDevice.PresentationParameters.BackBufferWidth),my=m.Y*680/Math.Max(1,GraphicsDevice.PresentationParameters.BackBufferHeight);if(Press(k,Keys.Escape))Exit();if(Press(k,Keys.Left))slot=(slot+2)%3;if(Press(k,Keys.Right))slot=(slot+1)%3;if(Press(k,Keys.Up))action=(action+5)%6;if(Press(k,Keys.Down))action=(action+1)%6;if(Press(k,Keys.Enter))Launch();if(m.LeftButton==ButtonState.Pressed&&previous.LeftButton==ButtonState.Released){for(int i=0;i<3;i++)if(new Rectangle(55+i*300,155,280,100).Contains(mx,my))slot=i;for(int i=0;i<6;i++)if(new Rectangle(70,290+i*37,520,32).Contains(mx,my)){action=i;Launch();}}old=k;previous=m;base.Update(time);}
 protected override void Draw(GameTime time){GraphicsDevice.SetRenderTarget(target);GraphicsDevice.Clear(new Color(19,34,39));batch.Begin(SpriteSortMode.Deferred,BlendState.NonPremultiplied,SamplerState.PointClamp,null,null);Box(35,35,930,610,new Color(31,49,53));Text("GREYHAVEN",65,63,Color.Gold);Text("A single-player journey",65,99);for(int i=0;i<3;i++){var store=new CampaignStore(package.Root,"slot"+(i+1));Box(55+i*300,155,280,100,i==slot?new Color(105,83,45):new Color(44,62,65));Text("CAMPAIGN "+(i+1),70+i*300,170);string label="Empty";if(store.Exists){try{var save=store.Latest();label=save.SavedUtc.ToString("yyyy-MM-dd HH:mm")+" UTC";}catch{label="Needs recovery";}}Text(label,70+i*300,208);}for(int i=0;i<6;i++){if(i==action)Box(65,287+i*37,530,32,new Color(105,83,45));Text(actions[i],80,294+i*37);}Text("Left / right: choose campaign",620,310);Text("Up / down: choose action",620,345);Text("Enter: begin   Esc: quit",620,380);Text("No campaign is overwritten",620,445);Text("by starting a new game.",620,470);Text(message.Length>98?message[..98]:message,55,550,Color.Salmon);Text("Original art, sound, text and world. Tile-authoritative movement.",55,610);batch.End();GraphicsDevice.SetRenderTarget(null);GraphicsDevice.Clear(Color.Black);batch.Begin(SpriteSortMode.Deferred,BlendState.Opaque,SamplerState.LinearClamp,null,null);batch.Draw(target,new Rectangle(0,0,GraphicsDevice.PresentationParameters.BackBufferWidth,GraphicsDevice.PresentationParameters.BackBufferHeight),Color.White);batch.End();if(capture!=null&&++frames==10){using var f=File.Create(capture);target.SaveAsPng(f,1000,680);Exit();}base.Draw(time);}
 protected override void UnloadContent(){target.Dispose();font.Dispose();pixel.Dispose();batch.Dispose();base.UnloadContent();}
}
